-- 阶段3：仪器设备业务闭环。应用启动时会幂等创建同结构表、菜单及演示数据。
CREATE TABLE HXS_LAB_INSTRUMENT (ID RAW(16) NOT NULL, INSTRUMENT_CODE VARCHAR2(50 CHAR) NOT NULL, INSTRUMENT_NAME VARCHAR2(150 CHAR) NOT NULL, CATEGORY_ID RAW(16), MODEL VARCHAR2(100 CHAR), MANUFACTURER VARCHAR2(150 CHAR), SUPPLIER_ID RAW(16), LAB_ID RAW(16) NOT NULL, LOCATION_ID RAW(16) NOT NULL, STATUS VARCHAR2(20 CHAR) DEFAULT 'normal' NOT NULL, DESCRIPTION VARCHAR2(500 CHAR), IS_ACTIVE NUMBER(1) DEFAULT 1 NOT NULL, CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_HXS_LAB_INSTRUMENT PRIMARY KEY (ID), CONSTRAINT UK_HXS_LAB_INSTRUMENT_CODE UNIQUE (INSTRUMENT_CODE));
CREATE TABLE HXS_LAB_BOOKING (ID RAW(16) NOT NULL, BOOKING_NO VARCHAR2(40 CHAR) NOT NULL, INSTRUMENT_ID RAW(16) NOT NULL, APPLICANT_ID RAW(16) NOT NULL, GROUP_ID RAW(16), START_TIME TIMESTAMP(6) NOT NULL, END_TIME TIMESTAMP(6) NOT NULL, PURPOSE VARCHAR2(500 CHAR) NOT NULL, STATUS VARCHAR2(20 CHAR) NOT NULL, APPROVER_ID RAW(16), APPROVE_TIME TIMESTAMP(6), APPROVE_REMARK VARCHAR2(500 CHAR), CANCEL_TIME TIMESTAMP(6), CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_HXS_LAB_BOOKING PRIMARY KEY (ID), CONSTRAINT UK_HXS_LAB_BOOKING_NO UNIQUE (BOOKING_NO));
CREATE INDEX IDX_HXS_LAB_BOOKING_TIME ON HXS_LAB_BOOKING (INSTRUMENT_ID, START_TIME, END_TIME, STATUS);
CREATE TABLE HXS_LAB_USAGE (ID RAW(16) NOT NULL, INSTRUMENT_ID RAW(16) NOT NULL, BOOKING_ID RAW(16), USER_ID RAW(16) NOT NULL, START_TIME TIMESTAMP(6) NOT NULL, END_TIME TIMESTAMP(6) NOT NULL, EXPERIMENT_CONTENT VARCHAR2(1000 CHAR) NOT NULL, REMARK VARCHAR2(500 CHAR), CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_HXS_LAB_USAGE PRIMARY KEY (ID));
CREATE TABLE HXS_LAB_REPAIR (ID RAW(16) NOT NULL, REPAIR_NO VARCHAR2(40 CHAR) NOT NULL, INSTRUMENT_ID RAW(16) NOT NULL, REPORTER_ID RAW(16) NOT NULL, FAULT_DESCRIPTION VARCHAR2(1000 CHAR) NOT NULL, STATUS VARCHAR2(20 CHAR) NOT NULL, APPROVER_ID RAW(16), APPROVE_TIME TIMESTAMP(6), REPAIRER VARCHAR2(100 CHAR), REPAIR_CONTENT VARCHAR2(1000 CHAR), REPAIR_START_TIME TIMESTAMP(6), REPAIR_END_TIME TIMESTAMP(6), REMARK VARCHAR2(500 CHAR), CREATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, UPDATE_TIME TIMESTAMP(6) DEFAULT SYSTIMESTAMP NOT NULL, CONSTRAINT PK_HXS_LAB_REPAIR PRIMARY KEY (ID), CONSTRAINT UK_HXS_LAB_REPAIR_NO UNIQUE (REPAIR_NO));
